#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n;
    cin >> n;
    map<long long, long long> freq;
    long long largest = 0;
    for (long long i = 0; i < n; i++) {
        long long c;
        cin >> c;
        freq[c]++;
        largest = max(largest, c);
    }
    long long best = n * (largest + 1);
    // No packet count above largest+1 can improve: each type then needs k-c more cards,
    // and the total strictly increases with k.
    for (long long k = 2; k <= largest + 1; k++) {
        long long added = 0;
        for (auto &[count, f] : freq) added += f * ((k - count % k) % k);
        best = min(best, added);
    }
    cout << best << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) next();
        TreeMap<Long, Long> freq = new TreeMap<>();
        long largest = 0;
        for (int i = 0; i < n; i++) {
            long c = next();
            freq.merge(c, 1L, Long::sum);
            largest = Math.max(largest, c);
        }
        long[] counts = new long[freq.size()], mult = new long[freq.size()];
        int t = 0;
        for (Map.Entry<Long, Long> e : freq.entrySet()) {
            counts[t] = e.getKey();
            mult[t++] = e.getValue();
        }
        long best = n * (largest + 1);
        // No packet count above largest+1 can improve: each type then needs k-c more cards,
        // and the total strictly increases with k.
        for (long k = 2; k <= largest + 1; k++) {
            long added = 0;
            for (int i = 0; i < t; i++) added += mult[i] * ((k - counts[i] % k) % k);
            best = Math.min(best, added);
        }
        System.out.println(best);
    }
}
